create.example:
// client
const bellHint = kcds.ui.ActionHint.create(
  { key: 'primary_action', text: 'Ring the bell', mode: 'hold', holdDuration: 2 },
  () => {
    kcds.core.Events.toServer('ringBell');
  },
);

create.exampleCs:
// client
var bellHint = ActionHint.Create(new { key = "primary_action", text = "Ring the bell", mode = "hold", holdDuration = 2 }, () =>
{
    Events.ToServer("ringBell");
});

shown.example:
// client: draw the hints yourself, with the game's hidden
const { Hud, ActionHint } = kcds.ui;

Hud.setHudPart('Hints', false);
kcds.core.Events.on('actionHintsChanged', () => {
  const lines = ActionHint.shown().map((hint) => `[${hint.key}] ${hint.text}`);
  console.log(lines.join(' | '));
});

shown.exampleCs:
// client: draw the hints yourself, with the game's hidden
Hud.SetHudPart("Hints", false);
Events.On("actionHintsChanged", () =>
{
    var lines = ActionHint.Shown().Select((hint) => $"[{hint["key"]}] {hint["text"]}");
    Log.Info(string.Join(" | ", lines));
});

